const paths={book:'M4 4h6a4 4 0 0 1 4 4v13a6 6 0 0 0-5-3H4zM20 4h-3v14h3z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',library:'M4 4v16M9 4v16M14 4v16m3-15 4 14M3 21h19',search:'M16 16l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4',history:'M3 11a9 9 0 1 1 2.4 7M3 5v6h6m3-5v6l4 2',file:'M14 3H5v18h14V8zM14 3v5h5M8 12h8m-8 4h6',report:'M14 3H5v18h14V8zM14 3v5h5M8 16v-3m4 3v-5m4 5v-2',users:'M12 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v2',settings:'m10 3-1 3-3 1-3 3v4l3 3 3 1 1 3h4l1-3 3-1 3-3v-4l-3-3-3-1-1-3zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',logout:'M9 3H4v18h5m5-14 5 5-5 5m-6-5h11',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zm-4 9 3 3 5-6',check:'m5 12 4 4L19 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10M10 21h4',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',edit:'m16 3 5 5-12 12-6 1 1-6zM13 6l5 5',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6m0-10v.1',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7m13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',building:'M4 21V6l8-3 8 3v15M8 8v1m8-1v1m-8 3v1m8-1v1m-6 8v-5h4v5M2 21h20',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M9 8a3 3 0 0 1 6 1c0 2-3 2-3 5m0 3v.1',lock:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3m-4 5v2',leaf:'M4 20 17 7M4 16C1 5 13 3 21 3c0 9-2 18-13 16',server:'M3 3h18v7H3zM3 14h18v7H3zM7 6h.1M7 17h.1m4-11h6m-6 11h6',filter:'M3 4h18l-7 8v7-9z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={registrado:'Registrado',en_revision:'En revisión',observado:'Observado',aprobado:'Aprobado',archivado:'Archivado',pendiente:'Pendiente',procesando:'Procesando',completado:'Completado',error:'Requiere atención',alta:'Alta relevancia',media:'Relevancia media',baja:'Baja relevancia'};
const roles={admin:'Administrador',coordinator:'Coordinador',reviewer:'Docente revisor',student:'Estudiante'};
const badge=s=>`<span class="badge ${e(s)}">${e(statuses[s]||s)}</span>`;
const date=s=>s?new Intl.DateTimeFormat('es-BO',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/La_Paz'}).format(new Date(s.includes('T')?s:s.replace(' ','T')+'-04:00')):'—';
const initials=s=>String(s||'').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const $=(s,root=document)=>root.querySelector(s),app=$('#app'),modal=$('#modal');
let user=null,csrf='',institution='',careers=[],pageToken=0,pollTimer=null,toastTimer=null;
let filters={q:'',status:'',career_id:'',page:1};
const staff=()=>user&&user.role!=='student';
const writable=p=>user.role==='admin'||Number(p.owner_id)===Number(user.id)||(user.role==='coordinator'&&Number(p.career_id)===Number(user.career_id));
async function api(action,{method='GET',body=null,id=null,params={}}={}){const q=new URLSearchParams({action,...params});if(id!=null)q.set('id',id);const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=csrf;const opts={method,headers,credentials:'same-origin'};if(body instanceof FormData)opts.body=body;else if(body!==null){headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}const response=await fetch(`api.php?${q}`,opts);let data;try{data=await response.json();}catch{throw new Error('Respuesta del servidor inválida. Revisa Apache y los límites de carga de PHP.');}if(!response.ok){if(response.status===401&&action!=='login'&&user){user=null;loginView();}throw new Error(data.error||'No se pudo completar la solicitud.');}return data;}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',6000);}
const button=(text,ico='plus',cls='primary',attrs='')=>`<button class="button ${cls}" ${attrs}>${icon(ico)}${text}</button>`;
const heading=(title,subtitle,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;
const notice=(text,type='')=>`<div class="notice ${type}">${icon(type==='success'?'check':'info')}<div>${text}</div></div>`;
const empty=(title,text,link='')=>`<div class="empty">${icon('book')}<h3>${title}</h3><p>${text}</p>${link}</div>`;
function showModal(title,html){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${html}</div>`;modal.showModal();}
modal.addEventListener('click',ev=>{if(ev.target.closest('[data-close]'))modal.close();});
function bindForm(selector,handler){const f=$(selector);if(!f)return;f.addEventListener('submit',async ev=>{ev.preventDefault();const b=$('[type=submit]',f),err=$('.form-error',f);if(err)err.textContent='';if(b)b.disabled=true;try{await handler(Object.fromEntries(new FormData(f)),f);}catch(ex){if(err)err.textContent=ex.message;else toast(ex.message,true);}finally{if(b)b.disabled=false;}});}
const careerOptions=(selected='')=>careers.map(c=>`<option value="${c.id}" ${Number(selected)===Number(c.id)?'selected':''}>${e(c.name)}</option>`).join('');
const brand=()=>`<div class="brand"><span class="brand-icon">${icon('book')}</span><div><div class="brand-name">ThesisGuard<span>AI</span></div><span class="brand-sub">Investigación con evidencia</span></div></div>`;
function loginView(){clearTimeout(pollTimer);document.title='Acceso · ThesisGuard';app.innerHTML=`<div class="login-page"><section class="login-story">${brand()}<div class="login-orbit"></div><div class="login-message"><div class="eyebrow">Un nuevo capítulo para tu investigación</div><h1>Grandes ideas.<br>Mejor investigación.<br><em>Más evidencia.</em></h1><p>Conecta el conocimiento de tu institución y acompaña cada tesis con una revisión más informada.</p><div class="login-pills"><span>${icon('library')}Repositorio académico</span><span>${icon('spark')}Asistencia con Gemini</span></div></div><div class="login-story-footer">ThesisGuard · Gestión y revisión académica · Bolivia</div></section><section class="login-form-area"><div class="login-top">${icon('shield')}Espacio de acceso institucional</div><div class="login-form-inner"><div class="eyebrow">Tu espacio de investigación</div><h2>Qué bueno verte de nuevo.</h2><p>Inicia sesión para continuar con tus proyectos<br>y descubrir nuevas conexiones.</p><form id="login-form" class="form-stack"><div class="field"><label for="email">Correo electrónico</label><input id="email" name="email" type="email" placeholder="nombre@institucion.edu" autocomplete="username" required></div><div class="field"><label for="password">Contraseña</label><div class="password-wrap"><input id="password" name="password" type="password" placeholder="Ingresa tu contraseña" autocomplete="current-password" required><button type="button" class="icon-button" id="toggle-password" aria-label="Mostrar contraseña">${icon('eye')}</button></div></div><p class="form-error" role="alert"></p><button class="button primary" type="submit">Entrar a mi espacio ${icon('arrow')}</button></form><div class="login-footnote">${e(institution)}<br>Si necesitas acceso, contacta al administrador de tu institución.</div></div></section></div>`;$('#toggle-password').onclick=()=>{$('#password').type=$('#password').type==='password'?'text':'password';};bindForm('#login-form',async data=>{const r=await api('login',{method:'POST',body:data});user=r.user;csrf=r.csrf;filters={q:'',status:'',career_id:'',page:1};careers=(await api('careers')).items;shell();route();});}
const navigation=[['dashboard','grid','Panel general'],['projects','library','Repositorio'],['search','search','Buscar antecedentes'],['analyze','spark','Nuevo análisis'],['history','history','Historial de análisis'],['reports','report','Informes']];
function shell(){app.innerHTML=`<div class="layout"><div class="mobile-overlay" id="mobile-overlay"></div><aside class="sidebar">${brand()}<div class="workspace-label">ESPACIO ACADÉMICO</div><nav class="nav" aria-label="Navegación principal">${roleNavigation().map(([p,i,l])=>`<a href="#/${p}" data-nav="${p}">${icon(i)}${l}${p==='analyze'?'<span class="count">IA</span>':''}</a>`).join('')}</nav><div class="nav-separator"></div><div class="workspace-label">GESTIÓN</div><nav class="nav" aria-label="Administración"><a href="#/jobs" data-nav="jobs">${icon('server')}Procesamiento</a>${user.role==='admin'?`<a href="#/users" data-nav="users">${icon('users')}Usuarios y permisos</a><a href="#/settings" data-nav="settings">${icon('settings')}Configuración</a>`:''}<a href="#/help" data-nav="help">${icon('help')}Guía de uso</a></nav><div class="sidebar-bottom"><div class="assistant-card"><span class="sparkle">${icon('spark')}</span><h4>Ideas con fundamento.</h4><p>La IA acompaña. Tu criterio académico decide.</p><a href="#/analyze">Explorar el análisis ${icon('arrow')}</a></div><div class="profile"><a href="#/profile" class="avatar" aria-label="Mi cuenta">${e(initials(user.name))}</a><a href="#/profile" class="profile-copy"><strong>${e(user.name)}</strong><span>${e(roles[user.role])}</span></a><button class="icon-button" id="logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="inline-actions"><button class="icon-button mobile-toggle" id="mobile-toggle" aria-label="Abrir menú">${icon('menu')}</button><div class="breadcrumb">Espacio de trabajo ${icon('chevron')}<strong id="breadcrumb">Panel general</strong></div></div><div class="topbar-right"><form id="global-search" class="topbar-search">${icon('search')}<input name="q" aria-label="Buscar en el repositorio" placeholder="Buscar en el repositorio"><kbd>↵</kbd></form><span class="topbar-divider"></span><span class="top-date">${date(new Date().toISOString())}</span><a href="#/jobs" class="icon-button" aria-label="Estado de procesamiento">${icon('bell')}</a><a href="#/profile" class="avatar" aria-label="Mi cuenta">${e(initials(user.name))}</a></div></header><div class="content"><div id="view"></div><footer class="footer"><span>© ${new Date().getFullYear()} ThesisGuard · <span id="institution-footer">${e(institution)}</span></span><span class="footer-status"><i class="dot"></i>Sesión institucional</span></footer></div></main></div>`;$('#logout').onclick=async()=>{try{await api('logout',{method:'POST',body:{}});user=null;start();}catch(err){toast(err.message,true);}};const toggle=()=>{$('.sidebar').classList.toggle('open');$('#mobile-overlay').classList.toggle('open');};$('#mobile-toggle').onclick=toggle;$('#mobile-overlay').onclick=toggle;bindForm('#global-search',async data=>location.hash='/search?q='+encodeURIComponent(data.q));}
async function route(){if(!user)return;clearTimeout(pollTimer);const token=++pageToken;$('.sidebar')?.classList.remove('open');$('#mobile-overlay')?.classList.remove('open');const [path,qs='']=(location.hash.replace(/^#\/?/,'')||'dashboard').split('?'),[page,id]=path.split('/'),params=new URLSearchParams(qs);const titles={dashboard:currentPanel().title,workspace:currentPanel().workspace,projects:'Repositorio',project:'Detalle del proyecto',search:'Buscar antecedentes',analyze:'Nuevo análisis',history:'Historial de análisis',analysis:'Resultado del análisis',reports:'Informes',users:'Usuarios y permisos',settings:'Configuración',jobs:'Procesamiento',help:'Guía de uso',profile:'Mi cuenta',audit:'Auditoría'};$('#breadcrumb').textContent=titles[page]||'Página';document.title=`${titles[page]||'ThesisGuard'} · ThesisGuard`;document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===page||(page==='project'&&x.dataset.nav==='projects')||(page==='analysis'&&x.dataset.nav==='history')));$('#view').innerHTML='<div class="loading"><span class="loader"></span>Cargando tu espacio…</div>';try{const views={dashboard,workspace:()=>projects('workspace'),projects,project:()=>project(Number(id)),search:()=>search(params.get('q')||''),analyze:()=>analyze(params.get('project')),history,analysis:()=>analysis(Number(id)),reports,users,settings,jobs,help,profile,audit:()=>audit(Number(params.get('page')||1))};const result=await(views[page]||help)();if(token!==pageToken||!user)return;$('#view').innerHTML=result.html;result.bind?.();}catch(err){if(token===pageToken&&$('#view'))$('#view').innerHTML=`<div class="error-page">${notice(e(err.message),'error')}<a class="button ghost" href="#/dashboard">Volver al panel</a></div>`;}}
const heroArt=()=>`<svg class="hero-art" viewBox="0 0 420 300" aria-hidden="true"><defs><linearGradient id="hg-paper" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fffefa"/><stop offset="1" stop-color="#efe9db"/></linearGradient><linearGradient id="hg-gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#efce8c"/><stop offset="1" stop-color="#c99a3f"/></linearGradient><linearGradient id="hg-line" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#bcd8ef"/><stop offset="1" stop-color="#8fb8dc"/></linearGradient></defs><circle cx="228" cy="142" r="126" fill="none" stroke="#bcd8ef" stroke-opacity=".16"/><circle cx="228" cy="142" r="96" fill="none" stroke="#bcd8ef" stroke-opacity=".2" stroke-dasharray="2 8"/><circle cx="228" cy="142" r="66" fill="none" stroke="#ecc87e" stroke-opacity=".15"/><path d="M84 214 151 92 284 70 351 176 236 246z" fill="none" stroke="#bcd8ef" stroke-opacity=".2" stroke-dasharray="4 6"/><g transform="rotate(-11 190 150)"><rect x="126" y="74" width="118" height="152" rx="14" fill="#123a5c" stroke="#2d5878"/><path d="M146 102h58m-58 12h74m-74 12h44" stroke="#507a97" stroke-width="4" stroke-linecap="round"/></g><g transform="rotate(7 218 140)"><rect x="150" y="52" width="126" height="164" rx="15" fill="url(#hg-paper)" stroke="#e2d7c1"/><rect x="171" y="77" width="42" height="40" rx="9" fill="#e6eff8"/><path d="M181 88h22m-22 7h22m-22 7h14" stroke="#6f90ab" stroke-width="2.4" stroke-linecap="round"/><path d="M171 138h84m-84 10h84m-84 10h62m-62 20h44" stroke="#d6d4cc" stroke-width="4.4" stroke-linecap="round"/><circle cx="248" cy="186" r="17" fill="url(#hg-gold)"/><path d="m241 186 5 5 9-11" stroke="#173b57" stroke-width="2.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></g><g><rect x="70" y="188" width="112" height="64" rx="14" fill="#103052" stroke="#bcd8ef" stroke-opacity=".2"/><path d="M88 232v-14m12 14v-26m12 26v-20m12 20v-34m12 34v-25m12 25v-15" stroke="url(#hg-line)" stroke-width="6" stroke-linecap="round"/></g><g transform="translate(304 82)"><circle r="30" fill="#1a4468" stroke="#ecc87e" stroke-opacity=".3"/><path d="M0-15 4.4-4.4 15 0 4.4 4.4 0 15-4.4 4.4-15 0-4.4-4.4z" fill="#ecc87e"/></g><circle cx="110" cy="86" r="5" fill="#bcd8ef" fill-opacity=".7"/><circle cx="336" cy="216" r="4" fill="#ecc87e" fill-opacity=".8"/><circle cx="272" cy="252" r="3" fill="#bcd8ef" fill-opacity=".55"/><path d="M110 86 190 60M336 216 300 180M272 252 340 238" stroke="#bcd8ef" stroke-opacity=".16" stroke-dasharray="2 5"/></svg>`;
function projectRows(items){return items.map(p=>`<tr><td><a href="#/project/${p.id}" class="project-cell"><span class="file-icon">${icon('file')}</span><div><strong>${e(p.title)}</strong><small>${e(p.authors)}${p.is_demo==1?'<span class="demo-tag">Demo</span>':''}</small></div></a></td><td class="muted">${e(p.career.replace('Ingeniería de ','Ing. ').replace('Ingeniería ','Ing. '))}</td><td>${badge(p.status)}</td><td><a href="#/project/${p.id}" class="icon-button" aria-label="Ver proyecto">${icon('chevron')}</a></td></tr>`).join('');}
async function dashboard(){return roleDashboard();}
function bindNewProject(){document.querySelectorAll('[data-new-project]').forEach(x=>x.onclick=()=>projectForm());}
function projectForm(p=null){const cs=user.role==='admin'?careers:careers.filter(c=>Number(c.id)===Number(user.career_id));showModal(p?'Editar proyecto':'Un nuevo proyecto, una nueva idea',`<form id="project-form"><div class="form-grid"><div class="field full"><label for="project-title">Título del proyecto</label><input id="project-title" name="title" value="${e(p?.title)}" maxlength="500" placeholder="¿Sobre qué trata tu investigación?" required></div><div class="field full"><label for="authors">Autores</label><input id="authors" name="authors" value="${e(p?.authors)}" maxlength="500" placeholder="Nombres completos, separados por coma" required></div><div class="field"><label for="career">Carrera</label><select id="career" name="career_id" required>${cs.map(c=>`<option value="${c.id}" ${Number(p?.career_id||user.career_id)===Number(c.id)?'selected':''}>${e(c.name)}</option>`).join('')}</select></div><div class="field"><label for="year">Gestión académica</label><input id="year" name="year" type="number" min="1950" max="2100" value="${p?.year||new Date().getFullYear()}" required></div><div class="field"><label for="modality">Modalidad</label><select id="modality" name="modality">${['Tesis de grado','Proyecto de grado','Trabajo dirigido','Tesis de posgrado'].map(x=>`<option ${p?.modality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="visibility">Visibilidad</label><select id="visibility" name="visibility">${[['career','Mi carrera'],['institution','Toda la institución'],['private','Autor y revisores de carrera']].map(([v,l])=>`<option value="${v}" ${(p?.visibility||'career')===v?'selected':''}>${l}</option>`).join('')}</select></div>${p&&['admin','coordinator'].includes(user.role)?`<div class="field full"><label for="status">Estado académico</label><select id="status" name="status">${['registrado','en_revision','observado','aprobado','archivado'].map(s=>`<option value="${s}" ${p.status===s?'selected':''}>${statuses[s]}</option>`).join('')}</select></div>`:''}<div class="field full"><label for="abstract">Resumen</label><textarea id="abstract" name="abstract" rows="4" maxlength="12000" required>${e(p?.abstract)}</textarea></div><div class="field full"><label for="keywords">Palabras clave</label><input id="keywords" name="keywords" value="${e(p?.keywords)}" maxlength="500" placeholder="Ej.: educación, aprendizaje automático"></div></div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="button" data-close>Cancelar</button><button type="submit" class="button primary">${icon('check')}${p?'Guardar cambios':'Crear proyecto'}</button></div></form>`);bindForm('#project-form',async data=>{const r=await api(p?'project':'projects',{method:p?'PATCH':'POST',id:p?.id,body:data});modal.close();toast('Proyecto guardado.');if(location.hash===`#/project/${r.id}`)route();else location.hash='/project/'+r.id;});}
async function projects(scope=''){const d=await api('projects',{params:{...filters,workspace:scope==='workspace'?1:0}});return{html:heading(scope==='workspace'?e(currentPanel().workspace):'Repositorio académico',scope==='workspace'?'Proyectos correspondientes a tus responsabilidades.':'Consulta los antecedentes a los que tienes acceso.',button('Nuevo proyecto','plus','primary','data-new-project'))+`<form class="filter-bar" id="project-filters"><div class="search-field">${icon('search')}<input name="q" aria-label="Buscar proyectos" placeholder="Buscar por título, autor o palabra clave…" value="${e(filters.q)}"></div><select name="career_id" aria-label="Filtrar por carrera"><option value="">Todas las carreras</option>${careerOptions(filters.career_id)}</select><select name="status" aria-label="Filtrar por estado"><option value="">Todos los estados</option>${['registrado','en_revision','observado','aprobado','archivado'].map(s=>`<option value="${s}" ${filters.status===s?'selected':''}>${statuses[s]}</option>`).join('')}</select><button class="button" type="submit">${icon('filter')}Filtrar</button></form>${d.items.length?`<div class="project-grid">${d.items.map(p=>`<a class="project-card" href="#/project/${p.id}"><div class="card-top"><span class="file-icon">${icon('file')}</span>${badge(p.status)}</div><div class="eyebrow muted" style="font-size:8px;letter-spacing:1px">${e(p.career)}${p.is_demo==1?'<span class="demo-tag">Demo</span>':''}</div><h3>${e(p.title)}</h3><p>${e(p.abstract)}</p><div class="card-meta">${icon('users')}${e(p.authors)}</div><div class="card-bottom"><span>${p.year} · ${p.document_count} documentos</span><span>Ver proyecto ${icon('arrow')}</span></div></a>`).join('')}</div><div class="pagination">${button('Anterior','chevron','','id="prev-page" '+(d.page<=1?'disabled':''))}<span>Página ${d.page} · ${d.total} proyectos</span>${button('Siguiente','arrow','','id="next-page" '+(d.page*12>=d.total?'disabled':''))}</div>`:empty('No encontramos proyectos','Prueba con otro filtro o registra un nuevo proyecto.')}`,bind:()=>{bindNewProject();bindForm('#project-filters',async data=>{filters={...data,page:1};route();});$('#prev-page')?.addEventListener('click',()=>{filters.page--;route();});$('#next-page')?.addEventListener('click',()=>{filters.page++;route();});}};}
async function project(id){const d=await api('project',{id}),p=d.project,can=writable(p),latest=d.documents.find(x=>x.status==='completado');return{html:heading('Detalle del proyecto','Cada documento cuenta una parte de tu investigación.',`<a class="button secondary" href="#/projects">${icon('library')}Repositorio</a>${can?button('Editar ficha','edit','','id="edit-project"'):''}`)+`<div class="two-column"><div class="stack"><section class="panel detail-header"><div class="inline-actions">${badge(p.status)}${p.is_demo==1?'<span class="demo-tag">Proyecto ficticio de demostración</span>':''}</div><h2>${e(p.title)}</h2><div class="detail-meta"><span>${icon('users')}${e(p.authors)}</span><span>${icon('building')}${e(p.career)}</span><span>${icon('clock')}${p.year}</span></div><div class="tags">${p.keywords.split(',').filter(Boolean).map(k=>`<span class="tag">${e(k.trim())}</span>`).join('')}</div><p class="prose">${e(p.abstract)}</p></section><section class="panel"><div class="panel-head"><div><h2>Documento y versiones</h2><p>Originales conservados con verificación SHA-256</p></div><span class="tag">${d.documents.length} versiones</span></div><div class="panel-body">${d.documents.length?d.documents.map(doc=>`<div class="version-row"><span class="file-icon">${icon('file')}</span><div class="version-copy"><strong>${e(doc.filename)}</strong><small>Versión ${doc.version} · ${(doc.size/1024).toFixed(0)} KB · ${date(doc.created_at)}</small>${doc.error?`<small style="color:#b77b67">${e(doc.error)}</small>`:''}</div>${badge(doc.status)}<button class="icon-button" data-document="${doc.id}" aria-label="Ver texto extraído">${icon('eye')}</button><a class="icon-button" href="api.php?action=download&id=${doc.id}" aria-label="Descargar documento">${icon('download')}</a></div>`).join(''):empty('Aún no hay documentos','Carga el PDF o Word de este proyecto.')}</div></section><section class="panel"><div class="panel-head"><div><h2>Historial de análisis</h2><p>Resultados asociados a este proyecto</p></div></div><div class="panel-body">${d.analyses.length?d.analyses.map(a=>`<a class="version-row" href="#/analysis/${a.id}"><span class="file-icon">${icon('spark')}</span><div class="version-copy"><strong>Análisis #${a.id}</strong><small>${e(a.model)} · ${date(a.created_at)}</small></div>${badge(a.status)}${icon('chevron')}</a>`).join(''):empty('La siguiente conexión está por descubrirse','Cuando el documento esté procesado, podrás solicitar un análisis con Gemini.')}</div></section></div><aside class="stack">${assignmentPanel(d)}${can?`<section class="panel"><div class="panel-head"><h3>Añadir una versión</h3>${icon('upload')}</div><div class="panel-body"><form id="upload-form"><label class="drop-zone" id="drop-zone">${icon('upload')}<strong>Tu investigación empieza aquí</strong><span>Arrastra tu documento o selecciona un archivo<br>PDF o DOCX · Hasta 10 MB</span><input type="file" name="file" accept=".pdf,.docx" aria-label="Seleccionar documento" required></label><p class="form-error" role="alert"></p><button type="submit" class="button primary" style="width:100%;margin-top:14px">${icon('upload')}Cargar documento</button></form></div></section><section class="panel"><div class="panel-head"><h3>Una mirada adicional</h3>${icon('spark')}</div><div class="panel-body"><p class="prose">Revisa la coherencia de tu investigación y encuentra conexiones con antecedentes del repositorio.</p>${latest?`<a class="button primary" href="#/analyze?project=${id}" style="width:100%;margin-top:18px">${icon('spark')}Analizar con Gemini</a>`:notice('Primero carga y procesa un documento.')}</div></section>`:''}<section class="panel"><div class="panel-head"><h3>Información del proyecto</h3></div><div class="panel-body"><div class="key-value"><span>Modalidad</span><strong>${e(p.modality)}</strong></div><div class="key-value"><span>Visibilidad</span><strong>${e({career:'Mi carrera',institution:'Institucional',private:'Restringida'}[p.visibility])}</strong></div><div class="key-value"><span>Registrado</span><strong>${date(p.created_at)}</strong></div><div class="key-value"><span>Actualizado</span><strong>${date(p.updated_at)}</strong></div></div></section>${notice('Si una tarea falla, puedes reintentar desde <a href="#/jobs"><u>Procesamiento</u></a>.')}</aside></div>`,bind:()=>{bindAssignments(id);$('#edit-project')?.addEventListener('click',()=>projectForm(p));document.querySelectorAll('[data-document]').forEach(x=>x.onclick=()=>documentView(Number(x.dataset.document)));bindForm('#upload-form',async(_,f)=>{const file=$('[name=file]',f).files[0];if(!file)throw new Error('Selecciona un PDF o DOCX.');if(file.size>10*1024*1024)throw new Error('El archivo supera los 10 MB.');const r=await api('upload',{method:'POST',id,body:new FormData(f)});if(r.status==='error')throw new Error(r.error||'No se pudo extraer el texto del documento.');toast(r.status==='completado'?'Documento procesado. Ya puedes analizarlo.':'Documento en cola de procesamiento.');route();});const dz=$('#drop-zone');if(dz){dz.ondragover=ev=>{ev.preventDefault();dz.classList.add('dragover');};dz.ondragleave=()=>dz.classList.remove('dragover');dz.ondrop=ev=>{ev.preventDefault();dz.classList.remove('dragover');if(ev.dataTransfer.files.length)$('input',dz).files=ev.dataTransfer.files;};}if(d.documents.some(x=>['pendiente','procesando'].includes(x.status)))pollTimer=setTimeout(()=>{if(!modal.open&&!$('#upload-form input')?.files.length)route();},6000);}};}
async function documentView(id){try{const d=await api('document',{id}),ss=d.sections||{};showModal(`Documento · versión ${d.version}`,`<div class="inline-actions" style="margin-bottom:18px">${badge(d.status)}<span class="muted">${e(d.filename)}</span></div>${d.status==='completado'?`<div class="section-tabs">${Object.keys(ss).map((k,i)=>`<button class="tab ${!i?'active':''}" data-section="${e(k)}">${e({resumen:'Resumen',problema:'Problema',objetivos:'Objetivos',metodologia:'Metodología',resultados:'Resultados',referencias:'Referencias'}[k]||k)}</button>`).join('')}</div><div id="section-content" class="prose" style="max-height:330px;overflow:auto"></div><div class="info-strip">${icon('info')}Clasificación automática orientativa. Las tablas conservan su orden textual, sin su diseño visual.</div>`:notice(e(d.error||'El documento está esperando procesamiento.'),d.error?'error':'')}<div class="info-strip" style="word-break:break-all">SHA-256: ${e(d.sha256)}</div>`);if(d.status==='completado'){const select=k=>{$('#section-content').textContent=ss[k]||'No se reconoció contenido en este apartado.';modal.querySelectorAll('[data-section]').forEach(x=>x.classList.toggle('active',x.dataset.section===k));};select(Object.keys(ss)[0]);modal.querySelectorAll('[data-section]').forEach(x=>x.onclick=()=>select(x.dataset.section));}}catch(err){toast(err.message,true);}}
async function search(q){const d=q?await api('projects',{params:{q}}):null;return{html:heading('El conocimiento se construye en conjunto.','Explora antecedentes dentro del repositorio al que tienes acceso.')+`<section class="panel"><div class="search-hero"><span class="sparkle">${icon('search')}</span><h2>¿Qué idea quieres explorar?</h2><p>Busca por tema, título, autor o palabras clave.<br>La búsqueda es textual y se limita a los proyectos de este repositorio.</p><form id="search-form"><div class="search-field">${icon('search')}<input name="q" value="${e(q)}" placeholder="Ej.: aprendizaje automático" aria-label="Consulta de antecedentes" required maxlength="200"></div><button class="button primary" type="submit">Buscar ${icon('arrow')}</button></form><div class="tags" style="justify-content:center">${['educación','sostenibilidad','datos personales'].map(s=>`<a class="tag" href="#/search?q=${encodeURIComponent(s)}">${s}</a>`).join('')}</div></div><div class="search-results">${d?(d.items.length?`<div class="panel-head"><h3>${d.total} resultados para “${e(q)}”</h3></div>${d.items.map(p=>`<article class="search-result"><div class="inline-actions"><span class="eyebrow muted">${e(p.career)}</span>${p.is_demo==1?'<span class="demo-tag">Demo</span>':''}</div><a href="#/project/${p.id}"><h3>${e(p.title)}</h3></a><p>${e(p.abstract)}</p><div class="card-meta">${e(p.authors)} · ${p.year}</div><a class="button ghost small" href="#/project/${p.id}">Consultar proyecto ${icon('arrow')}</a></article>`).join('')}${d.total>12?'<p class="info-strip">Primeros 12 resultados. Afina la búsqueda o utiliza el repositorio.</p>':''}`:empty('No hay coincidencias','Prueba una palabra más general.')):empty('Conecta con lo que ya se ha investigado','Los resultados aparecerán aquí. Usa después Gemini para comparar un documento con antecedentes seleccionados.')}</div></section>`,bind:()=>bindForm('#search-form',async data=>location.hash='/search?q='+encodeURIComponent(data.q))};}
async function analyze(projectId){
  const selected=projectId?await api('project',{id:projectId}):null,d=await api('projects',{params:{page:1}}),ws=d.items.filter(writable);
  const cs=user.role==='admin'?careers:careers.filter(c=>Number(c.id)===Number(user.career_id));
  const existing=!!selected;
  return{html:heading('Una segunda mirada a tu investigación.','Sube tu proyecto en PDF o elige uno del repositorio; Gemini revisa coherencia, metodología e indicios de coincidencia.')+`<div class="two-column"><div class="stack"><section class="panel upload-panel"><div class="panel-head"><div><h2>Sube un documento y analízalo</h2><p>La IA extrae el texto y lo contrasta con los antecedentes autorizados del repositorio.</p></div><span class="tag">Paso 1</span></div><div class="panel-body"><div class="steps"><div class="step active"><span>1</span>Documento</div><div class="step"><span>2</span>Análisis con IA</div><div class="step"><span>3</span>Evidencia</div></div><form id="analyze-form" class="form-stack" novalidate><div class="mode-switch" role="radiogroup" aria-label="Origen del documento"><label><input type="radio" name="mode" value="upload" ${existing?'':'checked'}><span>${icon('upload')}Subir PDF o DOCX</span></label><label><input type="radio" name="mode" value="existing" ${existing?'checked':''}><span>${icon('library')}Proyecto del repositorio</span></label></div><div class="mode-panel" id="mode-upload" ${existing?'hidden':''}><label class="drop-zone drop-zone-lg" id="analysis-zone">${icon('upload')}<strong>Arrastra aquí tu proyecto en PDF</strong><span>o selecciónalo desde tu equipo<br>PDF con texto o DOCX · Hasta 10 MB</span><input type="file" name="file" accept=".pdf,.docx" aria-label="Seleccionar documento para analizar"></label><div class="upload-file" id="upload-file" hidden></div><div class="form-grid upload-fields"><div class="field full"><label for="upload-title">Título del proyecto</label><input id="upload-title" name="title" maxlength="500" placeholder="Se completa con el nombre del archivo"></div><div class="field full"><label for="upload-authors">Autores</label><input id="upload-authors" name="authors" value="${e(user.name)}" maxlength="500"></div><div class="field"><label for="upload-career">Carrera</label><select id="upload-career" name="career_id">${cs.map(c=>`<option value="${c.id}" ${Number(user.career_id)===Number(c.id)?'selected':''}>${e(c.name)}</option>`).join('')}</select></div><div class="field"><label for="upload-year">Gestión académica</label><input id="upload-year" name="year" type="number" min="1950" max="2100" value="${new Date().getFullYear()}"></div></div><p class="upload-hint">El archivo se guarda como la primera versión del proyecto con su huella SHA-256. El resumen de la ficha se completa con el texto extraído y puedes editarlo después.</p></div><div class="mode-panel" id="mode-existing" ${existing?'':'hidden'}><div class="field"><label for="analysis-project">Proyecto de investigación</label><select id="analysis-project" name="project_id"><option value="">Selecciona un proyecto…</option>${[...(selected&&!ws.some(p=>p.id==projectId)?[selected.project]:[]),...ws].map(p=>`<option value="${p.id}" ${p.id==projectId?'selected':''}>${e(p.title)}</option>`).join('')}</select><small>Hasta 12 proyectos recientes. Para analizar otro, ábrelo desde el repositorio.</small></div>${selected?notice(`${e(selected.project.title)}<br>${selected.documents.some(x=>x.status==='completado')?'Se utilizará la última versión procesada correctamente.':'Este proyecto aún no tiene un documento procesado.'}`):''}${ws.length?'':notice('No tienes proyectos editables. Usa la carga de PDF para crear uno automáticamente.','warning')}</div><div class="field"><label>¿Qué revisará Gemini?</label><div class="tags"><span class="tag">Coherencia académica</span><span class="tag">Problema y objetivos</span><span class="tag">Metodología</span><span class="tag">Antecedentes</span><span class="tag">Indicios de plagio</span></div></div>${notice('Se envían a Google Gemini extractos del documento y hasta 6 antecedentes autorizados. La selección usa coincidencia léxica entre un máximo de 200 documentos recientes; no analiza toda la web.')}<label class="check-line"><input type="checkbox" name="consent" required><span>Confirmo que tengo autorización para enviar estos extractos a Google Gemini y entiendo que los resultados requieren revisión humana.</span></label><p class="form-error" role="alert"></p><div class="form-actions"><a class="button" href="#/projects">Volver al repositorio</a><button type="submit" class="button primary">${icon('spark')}<span data-submit-label>${existing?'Iniciar análisis':'Subir y analizar con Gemini'}</span></button></div></form></div></section></div><aside class="stack"><section class="panel"><div class="panel-head"><h3>De los datos a la evidencia</h3></div><div class="panel-body">${[['file','1. Documento verificable','Versión y huella del original registradas.'],['search','2. Antecedentes accesibles','La selección respeta los permisos del repositorio.'],['spark','3. Observaciones de Gemini','Las citas se contrastan con el texto enviado.'],['shield','4. Criterio docente','El dictamen académico lo registra una persona.']].map(([i,t,s])=>`<div class="activity-item"><div class="activity-icon">${icon(i)}</div><div><p>${t}</p><small>${s}</small></div></div>`).join('')}</div></section>${notice('La IA emite un veredicto orientativo de indicios de plagio limitado al repositorio. La calificación académica final requiere revisión humana.','warning')}${notice('Los PDF escaneados necesitan OCR. Los documentos complejos pueden perder tablas o ecuaciones al extraerse.')}</aside></div>`,bind:()=>{
    const form=$('#analyze-form'),error=$('.form-error',form),zone=$('#analysis-zone'),fileInput=$('[name=file]',form),fileBox=$('#upload-file'),label=$('[data-submit-label]',form);
    const mode=()=>$('input[name=mode]:checked',form).value;
    const syncMode=()=>{$('#mode-upload').hidden=mode()!=='upload';$('#mode-existing').hidden=mode()!=='existing';label.textContent=mode()==='upload'?'Subir y analizar con Gemini':'Iniciar análisis';};
    form.querySelectorAll('input[name=mode]').forEach(x=>x.addEventListener('change',syncMode));
    const describe=()=>{const file=fileInput.files[0];fileBox.hidden=!file;if(!file)return;fileBox.innerHTML=`<span class="file-icon">${icon('file')}</span><div class="version-copy"><strong>${e(file.name)}</strong><small>${(file.size/1024/1024).toFixed(2)} MB · ${/\.pdf$/i.test(file.name)?'PDF':'DOCX'}</small></div><span class="badge completado">Seleccionado</span>`;const title=$('#upload-title',form);if(title&&!title.value)title.value=file.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim();};
    fileInput.addEventListener('change',describe);
    zone.ondragover=ev=>{ev.preventDefault();zone.classList.add('dragover');};
    zone.ondragleave=()=>zone.classList.remove('dragover');
    zone.ondrop=ev=>{ev.preventDefault();zone.classList.remove('dragover');if(ev.dataTransfer.files.length){fileInput.files=ev.dataTransfer.files;describe();}};
    let created=null;
    const waitDocument=async id=>{for(let i=0;i<50;i++){const doc=await api('document',{id,params:{brief:1}});if(doc.status==='completado'||doc.status==='error')return doc;await new Promise(resolve=>setTimeout(resolve,1200));}return{status:'pendiente'};};
    form.addEventListener('submit',async ev=>{
      ev.preventDefault();
      if(error)error.textContent='';
      const current=mode(),submit=$('[type=submit]',form);
      try{
        if(!form.consent.checked)throw new Error('Confirma el envío de extractos a Google Gemini.');
        submit.disabled=true;
        if(current==='existing'){
          const pid=$('#analysis-project',form).value;
          if(!pid)throw new Error('Selecciona un proyecto del repositorio.');
          label.textContent='Revisando con Gemini…';
          const r=await api('analyze',{method:'POST',id:pid,body:{consent:true}});
          toast(r.status==='completado'?'Análisis listo.':r.status==='error'?'El análisis no pudo completarse.':'Gemini sigue revisando este análisis.');
          location.hash='/analysis/'+r.id;return;
        }
        const file=fileInput.files[0];
        if(!file)throw new Error('Selecciona el PDF o DOCX que quieres analizar.');
        if(!/\.(pdf|docx)$/i.test(file.name))throw new Error('Formato no admitido. Usa PDF o DOCX.');
        if(file.size>10*1024*1024)throw new Error('El archivo supera los 10 MB.');
        const title=($('#upload-title',form).value||file.name.replace(/\.[^.]+$/,'')).trim(),authors=$('#upload-authors',form).value.trim();
        if(!title)throw new Error('Escribe un título para el proyecto.');
        if(!authors)throw new Error('Indica los autores del proyecto.');
        if(!created){
          label.textContent='Creando el proyecto…';
          created=await api('projects',{method:'POST',body:{title,authors,career_id:$('#upload-career',form).value,year:$('#upload-year',form).value,modality:'Tesis de grado',visibility:'career',abstract:'Documento cargado desde '+file.name+'. El resumen se completará con el texto extraído.'}});
        }
        label.textContent='Extrayendo el texto del documento…';
        const payload=new FormData();payload.append('file',file);
        const up=await api('upload',{method:'POST',id:created.id,body:payload});
        let docState={status:up.status,error:up.error,text:up.excerpt||''};
        if(up.status==='pendiente'||up.status==='procesando'){label.textContent='Procesando el documento…';docState=await waitDocument(up.id);}
        if(docState.status==='error')throw new Error(docState.error||'No se pudo extraer el texto del documento.');
        if(docState.status!=='completado'){toast('El documento sigue en cola. Podrás analizarlo desde el proyecto.');location.hash='/project/'+created.id;return;}
        try{const excerpt=String(docState.text||docState.excerpt||'').trim();if(excerpt.length>120){let cut=excerpt.lastIndexOf('. ');cut=cut>160?cut+1:Math.min(1200,excerpt.length);await api('project',{method:'PATCH',id:created.id,body:{abstract:excerpt.slice(0,cut)}});}}catch(ignore){}
        label.textContent='Revisando con Gemini…';
        const r=await api('analyze',{method:'POST',id:created.id,body:{consent:true}});
        toast(r.status==='completado'?'Análisis listo.':r.status==='error'?'El análisis no pudo completarse.':'Gemini sigue revisando este análisis.');
        location.hash='/analysis/'+r.id;
      }catch(ex){if(error)error.textContent=ex.message;}
      finally{submit.disabled=false;if(!location.hash.startsWith('#/analysis/'))label.textContent=current==='upload'?'Subir y analizar con Gemini':'Iniciar análisis';}
    });
  }};
}
async function history(){const d=await api('analyses');return{html:heading('El recorrido de tus revisiones.','Consulta los análisis, sus documentos y las observaciones registradas.',`<a href="#/analyze" class="button primary">${icon('spark')}Nuevo análisis</a>`)+`<section class="panel">${d.items.length?`<div class="table-wrap"><table><thead><tr><th>PROYECTO</th><th>MODELO</th><th>ESTADO</th><th>REVISIONES</th><th>FECHA</th><th></th></tr></thead><tbody>${d.items.map(a=>`<tr><td><a class="project-cell" href="#/analysis/${a.id}"><span class="file-icon">${icon('spark')}</span><div><strong>${e(a.title)}</strong><small>Análisis #${a.id} · ${e(a.requester)}</small></div></a></td><td class="muted">${e(a.model)}</td><td>${badge(a.status)}</td><td>${a.review_count}</td><td class="muted">${date(a.created_at)}</td><td><a class="icon-button" href="#/analysis/${a.id}" aria-label="Ver análisis">${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div><div class="panel-footer">Últimos 100 análisis autorizados</div>`:empty('Tu primer análisis está por comenzar','Carga un documento y solicita una revisión con Gemini.','<a href="#/analyze" class="button primary">Preparar un análisis</a>')}</section>`};}
function integralResult(r,s){const v=r.verdict,comparisons=r.comparisons||[];let m=r.match;if(!m){const base={alta:0,media:0,baja:0};comparisons.forEach(c=>{if(base[c.relevance]!=null)base[c.relevance]++});m={verified:comparisons.length,examined:s.candidates.length,by_relevance:base,index:Math.round(Math.min(100,(base.alta*3+base.media*2+base.baja)/(3*Math.max(1,s.candidates.length))*100))}}const by=m.by_relevance||{};const kinds={sin_indicios:['ok','Sin indicios de plagio','check'],indicios_menores:['warn','Indicios leves de plagio','eye'],indicios_relevantes:['bad','Indicios relevantes de plagio','info']};const k=v?kinds[v.result]:null;const risk={bajo:'Riesgo bajo',medio:'Riesgo medio',alto:'Riesgo alto'}[v?.risk]||'Sin clasificar';const pct=Math.max(0,Math.min(100,Number(m.index??0)));const rel=x=>Number(by[x]||0);const dimensions=(r.dimensions||[]).map(d=>`<article class="dimension"><div class="dimension-top"><h4>${e(d.name)}</h4><span class="dimension-score">${d.score}/5</span></div><div class="dimension-bar"><i style="width:${Math.max(0,Math.min(5,Number(d.score)))/5*100}%"></i></div><p>${e(d.assessment)}</p></article>`).join('');return`<section class="panel integral-result"><div class="panel-head"><div><h2>Resultado integral del análisis</h2><p>Veredicto orientativo, dimensiones evaluadas y coincidencias verificadas</p></div>${icon('shield')}</div><div class="panel-body">${k?`<div class="verdict ${k[0]}"><span class="verdict-icon">${icon(k[2])}</span><div class="verdict-copy"><span class="verdict-eyebrow">VEREDICTO DE LA IA</span><h3>${e(v.headline)}</h3><p>${e(v.assessment)}</p></div><span class="verdict-pill">${k[1]}</span></div>`:`<div class="verdict plain"><span class="verdict-icon">${icon('info')}</span><div class="verdict-copy"><span class="verdict-eyebrow">VEREDICTO DE LA IA</span><h3>Este análisis no incluye el veredicto integral</h3><p>Fue generado con una versión anterior. Solicita un nuevo análisis del proyecto para obtener el dictamen completo con dimensiones e índice de coincidencia.</p></div><span class="verdict-pill">Versión anterior</span></div>`}<div class="integral-metrics"><div class="metric"><div class="metric-head"><span>Puntaje ponderado de evidencia</span><strong>${pct}/100</strong></div><div class="meter"><i style="width:${pct}%"></i></div><small>Escala orientativa basada en la relevancia que la IA asigna a las citas verificadas y en el número de antecedentes comparados. No mide porcentaje de texto coincidente ni determina plagio.</small></div><div class="metric"><div class="metric-head"><span>Valoración orientativa de la IA</span><strong>${risk}</strong></div><p class="metric-note">${v?`${rel('alta')} coincidencias de relevancia alta y ${rel('media')} de relevancia media sobre ${Number(m.examined??s.candidates.length)} antecedentes comparados.`:'Sin clasificación disponible para este análisis.'}</p></div></div><div class="match-counts"><div><strong>${Number(m.verified??r.comparisons.length)}</strong><span>Coincidencias verificadas</span></div><div><strong>${Number(m.examined??s.candidates.length)}</strong><span>Antecedentes comparados</span></div><div><strong>${rel('alta')}</strong><span>Relevancia alta</span></div><div><strong>${rel('media')+rel('baja')}</strong><span>Relevancia media o baja</span></div></div>${dimensions?`<div class="conclusion-block"><h3>Dimensiones evaluadas</h3><div class="dimension-grid">${dimensions}</div></div>`:''}${r.conclusion?`<div class="conclusion-block"><h3>Conclusión</h3><p class="prose">${e(r.conclusion)}</p></div>`:''}${v?.actions?.length?`<div class="conclusion-block"><h3>Acciones recomendadas</h3><ul class="findings">${v.actions.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`:''}${notice('El veredicto es orientativo y se limita a los antecedentes autorizados del repositorio. La determinación de plagio requiere revisión documental y criterio humano.','warning')}</div></section>`;}
async function analysis(id){const a=await api('analysis',{id}),r=a.result,s=a.snapshot,can=Boolean(a.can_review);if(a.status!=='completado')return{html:heading('El análisis está en camino.',e(a.project.title))+`<section class="panel"><div class="empty">${a.status==='error'?icon('info'):'<span class="loader"></span>'}<h3>${a.status==='error'?'Necesitamos revisar este análisis':a.status==='procesando'?'Gemini está revisando los extractos':'Tu análisis está en la cola'}</h3><p>${e(a.error||'La revisión empieza en esta misma visita. Si Gemini aún responde, la página se actualiza sola.')}</p>${badge(a.status)}<div class="form-actions" style="justify-content:center"><a class="button" href="#/jobs">Ver procesamiento</a><a class="button primary" href="#/project/${a.project_id}">Volver al proyecto</a></div></div></section>`,bind:()=>{if(a.status!=='error')pollTimer=setTimeout(route,1500);}};return{html:heading('De la observación a la evidencia.',`Análisis #${id} · ${date(a.created_at)} · ${e(r.model||a.model)}`,button('Generar informe PDF','download','primary','id="generate-report"'))+`<div class="analysis-banner"><span class="sparkle">${icon('spark')}</span><div><h2>${e(a.project.title)}</h2><p>Revisión asistida completada · ${s.candidates.length} antecedentes · Documento v${s.source.version}<br>La interpretación final corresponde al equipo académico.</p></div></div><div class="two-column"><div class="stack"><section class="panel"><div class="panel-head"><h2>Síntesis de la investigación</h2>${icon('spark')}</div><div class="panel-body"><p class="prose">${e(r.summary)}</p></div></section>${[['strengths','Fortalezas identificadas','check'],['gaps','Aspectos por revisar','eye'],['recommendations','Recomendaciones','leaf']].map(([k,t,i])=>`<section class="panel"><div class="panel-head"><h2>${t}</h2>${icon(i)}</div><div class="panel-body"><ul class="findings">${r[k].map(x=>`<li>${e(x)}</li>`).join('')||'<li>Sin observaciones registradas.</li>'}</ul></div></section>`).join('')}<section class="panel"><div class="panel-head"><div><h2>Conexiones y evidencia textual</h2><p>Citas literales validadas contra los extractos analizados</p></div></div><div class="panel-body">${r.comparisons.length?r.comparisons.map(c=>`<article class="evidence">${badge(c.relevance)}<h3><a href="#/project/${c.project_id}">${e(c.title)}</a></h3><p>${e(c.explanation)}</p><div class="quote-grid"><blockquote><small>Documento analizado</small>${e(c.source_quote)}</blockquote><blockquote><small>Documento antecedente</small>${e(c.candidate_quote)}</blockquote></div><div class="evidence-actions">${Number.isInteger(Number(c.document_id))&&Number(c.document_id)>0?`<a class="button small" href="api.php?action=download&id=${Number(c.document_id)}">Descargar documento antecedente</a>`:''}</div>${can?`<form class="label-form" data-candidate="${c.project_id}" style="margin-top:16px"><label class="field">Relevancia según tu criterio<select name="relevance"><option value="0">0 · No relevante</option><option value="1">1 · Relación débil</option><option value="2">2 · Relevante</option><option value="3">3 · Muy relevante</option></select></label><button class="button small" type="submit" style="margin-top:9px">Guardar evaluación humana</button></form>`:''}</article>`).join(''):notice('No se obtuvieron comparaciones con citas verificables. Esto no acredita ausencia de similitudes.')}${r.discarded_evidence?notice(`${r.discarded_evidence} comparaciones descartadas porque sus citas no pudieron verificarse.`,'warning'):''}</div></section></div><aside class="stack"><section class="panel"><div class="panel-head"><h3>Alcance del análisis</h3></div><div class="panel-body"><div class="key-value"><span>Documento fuente</span><strong>Versión ${s.source.version}</strong></div><div class="key-value"><span>Caracteres enviados</span><strong>${s.source.sent_characters} / ${s.source.total_characters}</strong></div><div class="key-value"><span>Documentos examinados</span><strong>${s.examined}</strong></div><div class="key-value"><span>Antecedentes enviados</span><strong>${s.candidates.length}</strong></div><p class="prose" style="margin-top:16px">${e(r.limitations)}</p></div></section><section class="panel"><div class="panel-head"><h3>Revisión docente</h3>${icon('shield')}</div><div class="panel-body">${can?`<form id="review-form" class="form-stack"><div class="field"><label for="verdict">Dictamen</label><select id="verdict" name="verdict"><option value="pendiente">Continuar revisión</option><option value="observado">Con observaciones</option><option value="aprobado">Aprobar proyecto</option></select></div><div class="field"><label for="observations">Observaciones</label><textarea id="observations" name="observations" rows="3" required maxlength="8000"></textarea></div><div class="field"><label for="criteria">Criterios y evidencia considerados</label><textarea id="criteria" name="criteria" rows="2" required maxlength="4000"></textarea></div><div class="field"><label for="recommendations">Recomendaciones</label><textarea id="recommendations" name="recommendations" rows="2" maxlength="4000"></textarea></div><p class="form-error" role="alert"></p><button type="submit" class="button primary">${icon('check')}Guardar revisión</button></form>`:notice('Un docente autorizado puede registrar el dictamen.')}<div style="margin-top:15px">${a.reviews.map(v=>`<div class="review-card"><h4>${e(v.reviewer)}</h4>${badge(v.verdict)}<p style="margin-top:9px">${e(v.observations)}</p><p><strong>Criterios:</strong> ${e(v.criteria)}</p><p><strong>Recomendaciones:</strong> ${e(v.recommendations)}</p><small class="muted">${date(v.created_at)}</small></div>`).join('')||'<p class="prose">Aún no hay una revisión humana registrada.</p>'}</div></div></section>${notice('Las etiquetas humanas ayudan a evaluar relevancia. No entrenan automáticamente el modelo.')}</aside></div>${integralResult(r,s)}`,bind:()=>{$('#generate-report').onclick=async ev=>{const b=ev.currentTarget;b.disabled=true;try{const report=await api('reports',{method:'POST',id,body:{}});toast('Informe guardado. Iniciando descarga.');location.href=`api.php?action=download&type=report&id=${report.id}`;}catch(err){toast(err.message,true);}finally{b.disabled=false;}};bindForm('#review-form',async data=>{await api('review',{method:'POST',id,body:data});toast('Revisión docente registrada.');route();});document.querySelectorAll('.label-form').forEach(f=>{const saved=a.labels.find(x=>x.candidate_id==f.dataset.candidate);if(saved)$('select',f).value=saved.relevance;f.onsubmit=async ev=>{ev.preventDefault();const b=$('button',f);b.disabled=true;try{await api('label',{method:'POST',id,body:{candidate_id:Number(f.dataset.candidate),relevance:Number($('select',f).value)}});toast('Evaluación humana guardada.');}catch(err){toast(err.message,true);}finally{b.disabled=false;}};});}};}
async function reports(){const d=await api('reports');return{html:heading('Evidencia que puedes compartir.','Informes PDF conservados con los datos de su fecha de emisión.')+`<section class="panel">${d.items.length?`<div class="table-wrap"><table><thead><tr><th>INFORME / PROYECTO</th><th>EMITIDO POR</th><th>FECHA</th><th></th></tr></thead><tbody>${d.items.map(r=>`<tr><td><div class="project-cell"><span class="file-icon">${icon('report')}</span><div><strong>${e(r.title)}</strong><small>Informe #${r.id} · Análisis #${r.analysis_id} · ${e(r.institution)}</small></div></div></td><td>${e(r.author)}</td><td>${date(r.created_at)}</td><td><a class="button small" href="api.php?action=download&type=report&id=${r.id}">${icon('download')}PDF</a></td></tr>`).join('')}</tbody></table></div><div class="panel-footer">Últimas 100 emisiones. Los informes anteriores conservan su contenido original.</div>`:empty('Tu evidencia, lista para documentarse','Genera un informe desde cualquier análisis completado. Se conservará una copia verificable.','<a href="#/history" class="button primary">Consultar análisis</a>')}</section>`};}
async function jobs(){
 const d=await api('jobs');
 const actions=j=>j.can_process&&['error','pendiente','procesando'].includes(j.status)?button(j.status==='error'?'Reintentar':'Continuar','history','','data-job="'+j.id+'" data-action="'+(j.status==='error'?'retry':'process-job')+'"'):j.kind==='analysis'?'<a class="icon-button" href="#/analysis/'+j.target_id+'" aria-label="Ver análisis">'+icon('chevron')+'</a>':'';
 return {html:heading('Cada tarea tiene su seguimiento.','Procesamiento de documentos y análisis.',button('Actualizar','history','','id="refresh-jobs"'))+notice('Las cargas y los análisis se procesan al solicitarlos. Si una tarea quedó pendiente o se interrumpió, pulsa Continuar. Si falló, revisa el mensaje y pulsa Reintentar.')+
 '<section class="panel" style="margin-top:22px">'+(d.items.length?'<div class="table-wrap"><table><thead><tr><th>TAREA / PROYECTO</th><th>ESTADO</th><th>INTENTOS</th><th>FECHA</th><th></th></tr></thead><tbody>'+d.items.map(j=>'<tr><td><div class="project-cell"><span class="file-icon">'+icon(j.kind==='analysis'?'spark':'file')+'</span><div><strong>'+e(j.title)+'</strong><small>#'+j.id+' · '+(j.kind==='analysis'?'Análisis con Gemini':'Extracción documental')+'</small>'+(j.error?'<small style="max-width:440px;white-space:normal;color:#ad7560">'+e(j.error)+'</small>':'')+'</div></div></td><td>'+badge(j.status)+'</td><td>'+j.attempts+'/3</td><td>'+date(j.created_at)+'</td><td>'+actions(j)+'</td></tr>').join('')+'</tbody></table></div><div class="panel-footer">Últimas 100 tareas · Solo los responsables del proyecto pueden iniciar o reintentar su procesamiento.</div>':empty('Todo está en orden','Aquí podrás consultar las próximas tareas.'))+'</section>',bind:()=>{
 $('#refresh-jobs').onclick=route;
 document.querySelectorAll('[data-job]').forEach(b=>b.onclick=async()=>{
 clearTimeout(pollTimer);b.disabled=true;b.textContent='Procesando…';
 try{const r=await api(b.dataset.action,{method:'POST',id:b.dataset.job,body:{}});toast(r.status==='completado'?'Tarea completada.':r.status==='error'?(r.error||'La tarea no pudo completarse.'):'El procesador está ocupado. Espera y pulsa Continuar.',r.status==='error');route();}
 catch(err){toast(err.message,true);b.disabled=false;b.textContent=b.dataset.action==='retry'?'Reintentar':'Continuar';}
 });
 if(d.items.some(j=>['pendiente','procesando'].includes(j.status)))pollTimer=setTimeout(route,7000);
 }};
}

async function users(){const d=await api('users');return{html:heading('Un equipo, distintos permisos.','Gestiona quién participa y cuál es su alcance dentro de la institución.',button('Añadir usuario','plus','primary','id="add-user"'))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>CARRERA</th><th>ACCESO</th><th></th></tr></thead><tbody>${d.items.map(u=>`<tr><td><div class="project-cell"><span class="avatar">${e(initials(u.name))}</span><div><strong>${e(u.name)}</strong><small>${e(u.email)}</small></div></div></td><td>${e(roles[u.role])}</td><td class="muted">${e(u.career||'Todas')}</td><td>${u.active==1?'<span class="badge completado">Activo</span>':'<span class="badge archivado">Inactivo</span>'}</td><td>${u.id!=user.id?button(u.active==1?'Desactivar':'Activar','user','small','data-toggle-user="'+u.id+'" data-active="'+(u.active==1?'0':'1')+'"'):'<span class="tag">Tú</span>'}</td></tr>`).join('')}</tbody></table></div></section><div class="info-strip">${icon('shield')}Los estudiantes editan sus proyectos. Coordinación asigna docentes de su carrera; cada docente revisa los proyectos asignados. Administración gestiona toda la institución.</div>`,bind:()=>{$('#add-user').onclick=()=>{showModal('Añadir integrante',`<form id="user-form" class="form-stack"><div class="field"><label for="user-name">Nombre completo</label><input id="user-name" name="name" required maxlength="160"></div><div class="field"><label for="user-email">Correo electrónico</label><input id="user-email" name="email" type="email" required maxlength="254"></div><div class="field"><label for="user-password">Contraseña inicial</label><input id="user-password" name="password" type="password" minlength="12" maxlength="200" required autocomplete="new-password"><small>Al menos 12 caracteres. Puede cambiarse desde Mi cuenta.</small></div><div class="form-grid"><div class="field"><label for="role">Rol</label><select id="role" name="role">${Object.entries(roles).reverse().map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div class="field"><label for="user-career">Carrera</label><select id="user-career" name="career_id">${careerOptions()}</select></div></div><p class="form-error" role="alert"></p><button class="button primary" type="submit">Crear cuenta</button></form>`);bindForm('#user-form',async data=>{await api('users',{method:'POST',body:data});modal.close();toast('Cuenta creada.');route();});};document.querySelectorAll('[data-toggle-user]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('users',{method:'PATCH',id:b.dataset.toggleUser,body:{active:b.dataset.active==='1'}});toast('Acceso actualizado.');route();}catch(err){toast(err.message,true);b.disabled=false;}});}};}
async function settings(){const d=await api('settings');return{html:heading('Tu institución, tu espacio.','Personalización, conexión con Gemini y estado operativo.',`<a href="#/audit" class="button">${icon('history')}Ver auditoría</a>`)+`<div class="two-column"><div class="stack"><section class="panel"><div class="panel-head"><h2>Identidad institucional</h2>${icon('building')}</div><div class="panel-body"><form id="settings-form" class="form-stack"><div class="field"><label for="institution">Nombre de la institución</label><input id="institution" name="institution" value="${e(d.institution)}" maxlength="200" required><small>Se utilizará en la interfaz y en los próximos informes. Las emisiones anteriores conservan su nombre original.</small></div><p class="form-error" role="alert"></p><button class="button primary" type="submit">Guardar personalización</button></form></div></section><section class="panel"><div class="panel-head"><div><h2>Asistencia con Google Gemini</h2><p>Conexión desde el servidor, con respuestas verificables</p></div>${icon('spark')}</div><div class="panel-body"><div class="key-value"><span>Modelo configurado</span><strong>${e(d.model)}</strong></div><div class="key-value"><span>Credencial en servidor</span><strong>${d.key_configured?'Configurada · contenido oculto':'Pendiente'}</strong></div><div class="key-value"><span>Última comprobación</span><strong id="gemini-status">${e(d.gemini_status)}</strong></div><div id="gemini-message" style="margin-top:18px"></div><button class="button primary" id="check-gemini" style="margin-top:16px">${icon('spark')}Probar conexión real</button><p class="info-strip">La comprobación envía una petición breve y puede consumir cuota. La clave se administra en config/local.php o GEMINI_API_KEY.</p></div></section><section class="panel"><div class="panel-head"><h2>Respaldos y recuperación</h2>${icon('shield')}</div><div class="panel-body"><p class="prose">El respaldo incluye tablas, originales y PDFs, junto con un manifiesto de integridad. Se crea desde la consola del servidor. La restauración exige una base nueva y una carpeta vacía.</p><pre class="code">php scripts/backup.php<br>php scripts/restore.php RUTA_RESPALDO NUEVA_BASE CARPETA_VACIA</pre><a class="button ghost" href="#/help">Consultar guía ${icon('arrow')}</a></div></section></div><aside class="stack"><section class="panel"><div class="panel-head"><h3>Estado del sistema</h3>${icon('server')}</div><div class="panel-body"><div class="key-value"><span>PHP</span><strong>${e(d.php)}</strong></div><div class="key-value"><span>MySQL / MariaDB</span><strong>${e(d.database)}</strong></div><div class="key-value"><span>Tamaño de archivo</span><strong>Hasta ${d.max_upload_mb} MB</strong></div><div class="key-value"><span>Evaluaciones humanas</span><strong>${d.labels}</strong></div><div class="key-value"><span>Actividad del worker</span><strong>${d.worker_heartbeat?date(d.worker_heartbeat):'Sin registrar'}</strong></div><a href="#/jobs" class="button ghost">Ver tareas ${icon('arrow')}</a></div></section>${notice('El funcionamiento técnico no acredita calidad académica. Se necesita un corpus autorizado y evaluado por personas antes de su uso institucional.','warning')}</aside></div>`,bind:()=>{bindForm('#settings-form',async data=>{await api('settings',{method:'POST',body:data});institution=data.institution;$('#institution-footer').textContent=institution;toast('Identidad institucional actualizada.');});$('#check-gemini').onclick=async ev=>{const b=ev.currentTarget;b.disabled=true;$('#gemini-message').innerHTML='<span class="loader"></span>';try{const r=await api('gemini-check',{method:'POST',body:{}});$('#gemini-message').innerHTML=notice(e(r.message)+' Modelo: '+e(r.model),'success');$('#gemini-status').textContent='Verificado ahora';}catch(err){$('#gemini-message').innerHTML=notice(e(err.message),'error');$('#gemini-status').textContent='Conexión no verificada';}finally{b.disabled=false;}};}};}
async function audit(page){const d=await api('audit',{params:{page}});return{html:heading('Un registro de cada paso.','Trazabilidad de accesos y operaciones administrativas.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>ACCIÓN</th><th>RESPONSABLE</th><th>REFERENCIA</th><th>FECHA</th></tr></thead><tbody>${d.items.map(a=>`<tr><td>${e(a.action)}</td><td>${e(a.actor||'Sistema')}</td><td>${a.target_id?'#'+a.target_id:'—'}</td><td>${e(a.created_at)}</td></tr>`).join('')}</tbody></table></div></section><div class="pagination">${page>1?`<a class="button" href="#/audit?page=${page-1}">Anterior</a>`:''}<span>Página ${page} · ${d.total} registros</span>${page*25<d.total?`<a class="button" href="#/audit?page=${page+1}">Siguiente</a>`:''}</div>`};}
async function profile(){return{html:heading('Tu identidad en el equipo.','Consulta tu cuenta y mantén tus credenciales actualizadas.')+`<div class="two-column"><section class="panel"><div class="panel-head"><h2>Cambiar contraseña</h2>${icon('lock')}</div><div class="panel-body"><form id="password-form" class="form-stack"><div class="field"><label for="current-password">Contraseña actual</label><input type="password" name="current_password" id="current-password" autocomplete="current-password" required></div><div class="field"><label for="new-password">Nueva contraseña</label><input type="password" name="password" id="new-password" autocomplete="new-password" minlength="12" maxlength="200" required><small>Usa al menos 12 caracteres.</small></div><div class="field"><label for="repeat-password">Repite la nueva contraseña</label><input type="password" name="repeat" id="repeat-password" autocomplete="new-password" required></div><p class="form-error" role="alert"></p><button type="submit" class="button primary">Guardar nueva contraseña</button></form></div></section><section class="panel"><div class="panel-head"><h3>Mi cuenta</h3></div><div class="panel-body"><div class="key-value"><span>Nombre</span><strong>${e(user.name)}</strong></div><div class="key-value"><span>Correo</span><strong>${e(user.email)}</strong></div><div class="key-value"><span>Rol</span><strong>${e(roles[user.role])}</strong></div><div class="key-value"><span>Carrera</span><strong>${e(careers.find(c=>c.id==user.career_id)?.name||'Todas')}</strong></div></div></section></div>`,bind:()=>bindForm('#password-form',async(data,f)=>{if(data.password!==data.repeat)throw new Error('Las contraseñas no coinciden.');await api('profile',{method:'PATCH',body:data});f.reset();toast('Contraseña actualizada.');})};}
async function help(){return{html:heading('Una guía para empezar bien.','Del primer documento a una revisión fundamentada.')+`<div class="help-grid">${[['01','Organiza el proyecto','Registra título, autores, carrera, resumen y palabras clave. Elige quién puede consultar sus documentos. Al editar, los campos omitidos conservan su valor.','projects','Abrir repositorio'],['02','Carga y verifica el documento','Sube tu proyecto en PDF desde Nuevo análisis y la plataforma extrae el texto al instante. También puedes adjuntar versiones desde la ficha del proyecto. Cada carga conserva el original con su huella SHA-256.','jobs','Ver procesamiento'],['03','Solicita un análisis con Gemini','Al subir un PDF puedes lanzar el análisis en el mismo paso: se crea el proyecto, se envían extractos a Google y se comparan hasta 6 antecedentes autorizados. Una clave inválida o sin cuota produce un error visible.','analyze','Preparar análisis'],['04','Aplica el criterio académico','Revisa observaciones, evalúa relevancia y registra un dictamen docente. Emite un PDF con las evidencias y revisiones. Cada emisión queda conservada.','history','Consultar análisis']].map(([n,t,p,l,a])=>`<section class="panel help-step"><div class="number">${n}</div><h3>${t}</h3><p>${p}</p><a class="button ghost" href="#/${l}">${a} ${icon('arrow')}</a></section>`).join('')}</div><div class="stack" style="margin-top:22px">${notice('Los PDF escaneados requieren OCR externo. Las tablas Word conservan su posición textual; no se reproduce el diseño de celdas combinadas, imágenes, notas al pie ni ecuaciones complejas.','warning')}${notice('Coordinación asigna un docente desde la ficha del proyecto. El docente encuentra sus tareas en Mis proyectos asignados y registra allí sus dictámenes. El estudiante consulta las observaciones recibidas en su panel.')}</div>`};}
async function start(){try{const s=await api('session');user=s.user;csrf=s.csrf;institution=s.institution;if(user){careers=(await api('careers')).items;shell();await route();}else loginView();}catch(err){app.innerHTML=`<div class="content" style="max-width:750px;padding-top:100px">${brand()}${heading('Necesitamos preparar el servidor.','La aplicación no pudo conectarse a su configuración inicial.')}${notice(e(err.message),'error')}<p class="prose" style="margin:22px 0">Comprueba la conexión a la base de datos y la configuración del servidor. Consulta al administrador si el problema continúa.</p><button class="button primary" id="restart">Volver a comprobar</button></div>`;$('#restart').onclick=start;}}
window.addEventListener('hashchange',route);window.addEventListener('offline',()=>toast('Se perdió la conexión. Los trabajos guardados permanecen en el servidor.',true));start();

